  readonly flags: Readonly<Record<string, JsonValue>>; // Tier 3 的 feature A/B：experiment.flags 透传。没配时是 {}
  readonly experimentId?: string;  // 路径推导的实验 id，与结果里的 experimentId 同源。不经 experiment

